using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Xml.Linq;

public static class FarmBattleReviewTests
{
    private static void Check(bool ok,string label){if(!ok)throw new Exception("Battle review: "+label);}
    private static FarmGame New(string root){var g=new FarmGame(Path.Combine(root,"battle-review-"+Guid.NewGuid().ToString("N")+".xml"));g.S.LastFarmTicks=DateTime.UtcNow.AddDays(1).Ticks;return g;}
    private static void Start(FarmGame g,int region=0,int depth=0,int blessing=0){g.S.BlessingOffers=new[]{0,1,2};Check(g.BeginJourney(region,blessing,depth),"fixture departs");}
    public static string Run(string root)
    {
        var g=New(root);Start(g);g.RouteChoice(0);g.R.EnemyHp=new[]{1000,1000,0};g.R.EnemyMax=new[]{1000,1000,0};g.R.EnemyKind=new[]{0,0,0};g.R.ActiveBattle.EnemyStart=2000;g.R.Hp[0]=20;g.R.ActiveBattle.StartHp[0]=20;g.Step();var b=g.CurrentBattleNotes().Single();
        Check(b.Damage[0]==9&&b.Damage[2]==21&&b.Damage[3]==6&&b.Direct==36&&b.Healing==5&&b.SkillHealing[3]==5&&b.Blocked[0]==10&&b.Taken[0]==0,"one round counts real direct damage, actual skill healing and shield absorption");
        Check(b.Combos[0]==1&&b.Combos[1]==1&&b.Actions[2]==1&&b.EndHp[0]==25,"combo and action counts belong to this encounter");b.Damage[0]=999;Check(g.R.ActiveBattle.Damage[0]==9,"returned live review is detached");
        g.ToggleJourneyPause();g.Save();var reloaded=new FarmGame(g.SavePath);Check(reloaded.R.JourneyPaused&&reloaded.R.ActiveBattle.Direct==36&&reloaded.R.ActiveBattle.Healing==5,"unfinished paused record survives restart");g.Retreat();Check(g.R.Battles.Single().Outcome=="retreat"&&g.S.JourneyMemories.Single().Battles.Single().Direct==36,"retreat closes and stores active battle once");g.Save();Check(new FarmGame(g.SavePath).R.Battles.Length==1&&!g.Retreat(),"repeated result handling does not duplicate battle");
        var kill=New(root);Start(kill);kill.RouteChoice(0);kill.R.EnemyCount=1;kill.R.EnemyHp=new[]{1,0,0};kill.R.EnemyMax=new[]{1,0,0};kill.R.EnemyKind=new int[3];kill.R.ActiveBattle.EnemyStart=1;kill.R.Hp[0]=20;kill.R.ActiveBattle.StartHp[0]=20;kill.Step();b=kill.R.Battles.Single();Check(b.Direct==1&&b.Damage[0]==1&&b.Healing==0&&b.EndHp[0]==20&&kill.R.Hp[0]>20&&b.Actions.Sum()==1,"overkill and post-victory recovery excluded from encounter metrics");
        var clean=New(root);clean.S.Xp=Enumerable.Repeat(55,5).ToArray();clean.SetPoisonPreset();Start(clean);clean.AdvanceJourney(DateTime.UtcNow.AddHours(2));Check(clean.R.Outcome=="victory"&&clean.R.Battles.Length==4&&clean.R.Battles.Select(n=>n.Station).SequenceEqual(new[]{0,1,3,4}),"complete journey records four fights and no camp fight");
        foreach(var note in clean.R.Battles){Check(note.Direct+note.Burn+note.Poison==note.EnemyStart+note.EnemyHealing-note.EnemyRemaining,"actual damage conserves enemy health");Check(note.StartHp.Sum()+note.Healing-note.EndHp.Sum()==note.Taken.Sum(),"actual damage and healing conserve party health");Check(note.SkillHealing.Sum()<=note.Healing&&note.Damage.Sum()<=note.Direct,"attributed contributions never exceed totals");}
        var memory=clean.S.JourneyMemories.Single();int damage=memory.Battles[0].Direct;string name=memory.Battles[0].Names[0];clean.R.Battles[0].Direct++;Check(memory.Battles[0].Direct==damage,"history is detached from current run");clean.Home();clean.S.Evolved=true;clean.SetPreset(0);Check(memory.Battles[0].Names[0]==name&&memory.Battles[0].Levels.All(l=>l==3),"historical names and levels survive current evolution and team changes");
        var plain=New(root);var traced=New(root);foreach(var run in new[]{plain,traced}){run.S.Xp=Enumerable.Repeat(110,5).ToArray();run.S.Evolved=true;run.S.SeedStage=2;run.S.ExpeditionClears=Enumerable.Repeat(1,6).ToArray();run.SetPoisonPreset();Start(run,1,1,2);}plain.R.TraceBattles=false;
        plain.AdvanceJourney(DateTime.UtcNow.AddHours(2));traced.AdvanceJourney(DateTime.UtcNow.AddHours(2));Check(plain.R.Outcome==traced.R.Outcome&&plain.S.Fertilizer==traced.S.Fertilizer&&plain.S.Crystals==traced.S.Crystals&&plain.R.Hp.SequenceEqual(traced.R.Hp)&&plain.R.EnemyHp.SequenceEqual(traced.R.EnemyHp)&&plain.ComboReport==traced.ComboReport&&plain.S.Seed==traced.S.Seed,"recording does not change battle result, rewards, randomness or combo counts");
        var slow=New(root);slow.S.ExpeditionClears=new[]{1,1,0,0,0,0};Start(slow,0,2);slow.RouteChoice(0);slow.R.EnemyHp=new[]{500,500,0};slow.R.EnemyMax=new[]{1000,1000,0};slow.R.EnemyKind=new int[3];slow.R.ActiveBattle.EnemyStart=1000;slow.R.Round=59;slow.Step();b=slow.R.Battles.Single();Check(b.Reason=="round-limit"&&b.EnemyHealing==8&&FarmGame.BattleObservation(b).Contains("60 回合")&&FarmGame.BattleObservation(b).Contains("实际回复了 8"),"turn limit and actual regeneration are reported explicitly");
        var missing=New(root);missing.S.Team=new[]{2,1,4};Start(missing,0,0,1);missing.RouteChoice(0);missing.Step();b=missing.CurrentBattleNotes().Single();Check(b.Actions[2]>0&&b.Combos[0]==0&&FarmGame.BattleObservation(b).Contains("没有触发潮湿追击"),"only an attempted but inactive combo gets a diagnostic");
        var loss=New(root);Start(loss);loss.RouteChoice(0);loss.R.EnemyCount=3;loss.R.EnemyHp=loss.R.EnemyMax=new[]{1000,1000,1000};loss.R.EnemyKind=new[]{3,3,3};foreach(int pet in loss.S.Team)loss.R.Hp[pet]=1;loss.R.Round=2;loss.Step();b=loss.R.Battles.Single();Check(b.Reason=="exhausted"&&b.EndHp.Sum()==0&&b.FellRound.Where(x=>x>0).All(x=>x==3)&&FarmGame.BattleObservation(b).Contains("队伍体力耗尽"),"exhaustion and falling round captured");
        var offline=New(root);offline.S.Xp=Enumerable.Repeat(55,5).ToArray();Start(offline);offline.R.NextJourneyTicks=DateTime.UtcNow.AddHours(-1).Ticks;offline.Save();var settled=new FarmGame(offline.SavePath);Check(settled.R.Battles.Length==4&&settled.S.JourneyMemories.Single().Battles.Length==4&&new FarmGame(offline.SavePath).S.JourneyMemories.Length==1,"offline completion stores a full review once");
        var old=New(root);Start(old);old.RouteChoice(0);old.ToggleJourneyPause();var xml=XDocument.Load(old.SavePath);var runNode=xml.Root.Element("Run");runNode.Element("TraceBattles").Remove();runNode.Element("ActiveBattle").Remove();runNode.Element("Battles").Remove();string path=Path.Combine(root,"pre-battle-review.xml");xml.Save(path);var migrated=new FarmGame(path);Check(migrated.SavePath==path&&!migrated.R.TraceBattles&&migrated.R.ActiveBattle==null&&migrated.R.JourneyPaused,"old active journey retains pause without invented review");migrated.ToggleJourneyPause();migrated.AdvanceJourney(DateTime.UtcNow.AddHours(2));Check(migrated.R.Battles.Length==0&&migrated.S.JourneyMemories.All(m=>m.Battles.Length==0),"old-started journey remains unrecorded through completion");
        clean.S.JourneyMemories[0].Battles=new[]{memory.Battles[0],new BattleNote()};clean.Save();Check(clean.S.JourneyMemories[0].Battles.Length==1&&clean.S.JourneyMemories[0].Names.Length==3,"malformed optional details do not discard original history");
        return "PASS: actual damage and healing, overkill exclusion, shield absorption, turn counts, health conservation, four-fight journeys, outcome causes, inactive-combo observations, unchanged simulation, paused/offline persistence, immutable history and old-save compatibility.";
    }
}

public partial class FarmPanel
{
    private void ReviewRender(string root,string name,double width=924,double height=721){Render();UIPreview(root,name,width,height);}
    internal void RenderBattleReviewChecks(string root)
    {
        Action<bool,string> check=FarmHeadlessTests.Check;G.S.Xp=Enumerable.Repeat(55,5).ToArray();G.SetPoisonPreset();G.S.BlessingOffers=new[]{0,1,3};G.BeginJourney(0,0);G.RouteChoice(0);G.Step();G.ToggleJourneyPause();Tab="冒险";ReviewRender(root,"review-entry");
        int round=G.R.Round;long next=G.R.NextJourneyTicks;UIAction("逐场复盘 · 伤害与配合").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-live-small",764,571);check(Tab=="复盘"&&G.R.JourneyPaused&&G.R.Round==round&&G.R.NextJourneyTicks==next,"review opening preserves paused simulation");UIVisible(UIAction("回到冒险现场"),"review return visible at minimum size");check(!UIAction("调整配队与技能").IsEnabled,"cannot adjust party during active trip");
        G.ToggleJourneyPause();G.AdvanceJourney(DateTime.UtcNow.AddHours(2));Tab="冒险";ReviewRender(root,"review-result-entry");int fertilizer=G.S.Fertilizer,crystals=G.S.Crystals;UIAction("逐场复盘 · 伤害与配合").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-result");
        var lastPetCard=UIChildren<Border>((DependencyObject)Content).First(card=>card.Child is StackPanel&&UIChildren<TextBlock>(card).Any(t=>t.Text.StartsWith("3 · ")));var cardPoint=lastPetCard.TranslatePoint(new Point(0,0),(UIElement)Content);check(cardPoint.Y>=0&&cardPoint.Y+lastPetCard.ActualHeight<=681,"all three pet cards fit default review viewport");
        ReviewRender(root,"review-result-small",764,571);UIVisible(UIAction("返家并调整配队"),"party action visible in minimum result review");check(G.R.Phase=="result"&&G.S.Fertilizer==fertilizer&&G.S.Crystals==crystals,"review does not dismiss result or repeat rewards");
        UIAction("溪口 · 通关").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-first-fight");check(reviewStation==0&&G.R.Battles.Length==4,"encounter selector changes only displayed fight");UIAction("返家并调整配队").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-to-party");check(Tab=="配队"&&G.AtHome&&G.S.Fertilizer==fertilizer,"explicit action returns home and opens workshop");
        var memory=G.S.JourneyMemories[0];OpenHandbook(3);historyExpanded=memory.RecordedTicks;ReviewRender(root,"review-history-entry");UIAction("查看逐场复盘").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-history");check(reviewMemory==memory&&Tab=="复盘","history opens its own recorded encounters");
        int carePet=FarmGame.ReviewCarePet(memory.Battles.Last());UIAction("培养"+G.Name(carePet)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ReviewRender(root,"review-to-care");check(Tab=="培养"&&G.CurrentCarePlan.Pet==carePet&&!G.CurrentCarePlan.Evolution,"review targets the correct pet for level training");
        G.S.Xp=Enumerable.Repeat(0,5).ToArray();G.S.Evolved=true;G.S.ExpeditionClears=Enumerable.Repeat(1,6).ToArray();G.S.BlessingOffers=new[]{0,1,3};check(G.BeginJourney(1,0,2),"failure review fixture departs");G.AdvanceJourney(DateTime.UtcNow.AddHours(2));OpenBattleReview();ReviewRender(root,"review-defeat");check(G.R.Battles.Last().Reason=="exhausted"&&UIChildren<TextBlock>((DependencyObject)Content).Any(t=>t.Text.Contains("队伍体力耗尽")),"failure review explains observed cause");
        G.Home();OpenBattleReview(new JourneyMemory{Region=0,Depth=0});ReviewRender(root,"review-old-empty");check(UIChildren<TextBlock>((DependencyObject)Content).Any(t=>t.Text=="这一趟还没有逐场记录"),"old history has a truthful empty state");check(!IsVisible&&!owner.IsVisible,"review checks never show windows");
        File.WriteAllText(Path.Combine(root,"battle-review-ui-regression.txt"),"PASS: live review without pause changes; minimum-window return, workshop and care links; encounter selection; result and reward preservation; historical review identity; failure observations; old-history empty state. Isolated saves and offscreen controls only.");
    }
}
